def compute(vars):
    backlog = vars["v1"]
    fixed_price_percentage = vars["v2"]
    value = backlog * fixed_price_percentage / 100
    return {
        "value": value,
        "trace": {
            "backlog_million": backlog,
            "fixed_price_percentage": fixed_price_percentage,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
